// The previous theme (Chirpy) installed a cache-first service worker at this
// URL. Browsers keep checking it for updates, so this replacement removes it:
// it clears every cache, unregisters itself and reloads open pages, which then
// load straight from the network. Safe to delete once old visitors are gone.
self.addEventListener('install', () => self.skipWaiting());

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      for (const key of await caches.keys()) await caches.delete(key);
      await self.registration.unregister();
      for (const client of await self.clients.matchAll({ type: 'window' })) client.navigate(client.url);
    })(),
  );
});
